/// Set the text for this menu item. `text` could optionally contain
/// an `&` before a character to assign this character as the mnemonic
/// for this menu item. To display a `&` without assigning a mnemenonic, use `&&`.
pub fn set_text<S: AsRef<str>>(&self, text: S) -> crate::Result<()> {
  let text = text.as_ref().to_string();
  run_item_main_thread!(self, |self_: Self| (*self_.0).as_ref().set_text(text))
}

macro_rules! run_item_main_thread {
  ($self:ident, $ex:expr) => {{
    use std::sync::mpsc::channel;
    let (tx, rx) = channel();
    let self_ = $self.clone();
    let task = move || {
      let f = $ex;
      let _ = tx.send(f(self_));
    };
    $self
      .app_handle()
      .run_on_main_thread(task)
      .and_then(|_| rx.recv().map_err(|_| crate::Error::FailedToReceiveMessage))
  }};

fn send_user_message(&self, message: Message<T>) -> Result<()> {
  if current_thread().id() == self.main_thread_id {
    handle_user_message(
      &self.main_thread.window_target,
      message,
      UserMessageContext {
        window_id_map: &self.window_id_map,
        windows: &self.main_thread.windows,
      },
    );
    Ok(())
  } else {
    self
      .proxy
      .send_event(message)
      .map_err(|_| Error::FailedToSendMessage)
  }
}

